export default function NewsletterSubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);

  const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
  const errorText = touched && !isValid ? 'Укажите корректный адрес, например name@example.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;

    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${email.trim()}`,
      variant: 'success',
    });
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        maxWidth: 420,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        <span style={{ fontFamily: 'var(--jx-font-display)', fontSize: 20 }}>Подписка на рассылку</span>
        <span style={{ color: 'var(--jx-text-2)', fontSize: 14 }}>
          Раз в неделю присылаем письмо с новыми материалами. Отписаться можно в один клик.
        </span>
      </div>

      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="name@example.com"
        autoComplete="email"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        errorText={errorText}
        helperText={errorText ? undefined : 'Адрес используем только для рассылки'}
      />

      <div style={{ display: 'flex', gap: 8 }}>
        <JxButton type="submit" variant="primary">
          Подписаться
        </JxButton>
      </div>

      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="bottom-right" />
    </form>
  );
}

